import AppKit
import ImageIO
import MyScreenArtCore
import ProjectKit

/// Library card stills: the package's cached thumbnail file (generated by `ThumbnailGenerator` when missing),
/// decoded with ImageIO straight to the card's pixel size and kept in an `NSCache`. Never opens the video
/// except to generate a missing thumbnail once.
///
/// Owned by the Library window, so its memory goes away when the window closes.
@MainActor
final class ThumbnailLoader {
    /// Longest side of the generated thumbnail file.
    nonisolated static let generatedPixelSize = 640

    private final class Entry {
        let image: CGImage
        init(_ image: CGImage) { self.image = image }
    }

    private let cache = NSCache<NSString, Entry>()

    init() {
        cache.totalCostLimit = 48 * 1024 * 1024
        cache.countLimit = 400
    }

    /// Rounds a pixel size up to a 64-pixel bucket, so live resizing doesn't re-decode on every point.
    nonisolated static func bucket(_ pixels: Double) -> Int {
        let clamped = min(max(pixels, 64), Double(generatedPixelSize))
        return Int((clamped / 64).rounded(.up)) * 64
    }

    private static func key(_ item: ProjectKit.LibraryItem, _ maxPixelSize: Int) -> NSString {
        "\(item.package.url.path)|\(maxPixelSize)" as NSString
    }

    func cachedImage(for item: ProjectKit.LibraryItem, maxPixelSize: Int) -> CGImage? {
        cache.object(forKey: Self.key(item, maxPixelSize))?.image
    }

    /// The still for `item`, at most `maxPixelSize` on its longest side; nil if there's no screen video.
    func image(for item: ProjectKit.LibraryItem, maxPixelSize: Int) async -> CGImage? {
        if let cached = cachedImage(for: item, maxPixelSize: maxPixelSize) { return cached }
        guard
            let image = await Self.load(
                package: item.package, thumbnailURL: item.thumbnailURL, maxPixelSize: maxPixelSize)
        else { return nil }
        cache.setObject(Entry(image), forKey: Self.key(item, maxPixelSize), cost: image.bytesPerRow * image.height)
        return image
    }

    @concurrent
    private static func load(package: RecordingPackage, thumbnailURL: URL?, maxPixelSize: Int) async -> CGImage? {
        let url: URL
        if let thumbnailURL, FileManager.default.fileExists(atPath: thumbnailURL.path) {
            url = thumbnailURL
        } else {
            do {
                url = try await ThumbnailGenerator(maxPixelSize: generatedPixelSize).thumbnail(for: package)
            } catch {
                Log.app.error(
                    "No thumbnail for \(package.url.lastPathComponent, privacy: .public): \(error, privacy: .public)")
                return nil
            }
        }
        return decode(url, maxPixelSize: maxPixelSize)
    }

    /// Decodes a downsampled image (never the full-size bitmap).
    private nonisolated static func decode(_ url: URL, maxPixelSize: Int) -> CGImage? {
        let sourceOptions = [kCGImageSourceShouldCache: false] as CFDictionary
        guard let source = CGImageSourceCreateWithURL(url as CFURL, sourceOptions) else { return nil }
        let options =
            [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceCreateThumbnailWithTransform: true,
                kCGImageSourceShouldCacheImmediately: true,
                kCGImageSourceThumbnailMaxPixelSize: maxPixelSize,
            ] as CFDictionary
        return CGImageSourceCreateThumbnailAtIndex(source, 0, options)
    }
}
